import psycopg2
import re

class LicencePlateFinder:
    def __init__(self):
        self.allowed_chars = re.compile(r'^[a-zA-Z0-9]+$')

    def find_vehicles(self, db_cursor, licence_plate_fragment):
        if not self.allowed_chars.match(licence_plate_fragment):
            raise ValueError("Invalid licence plate fragment")
        query = "SELECT * FROM vehicles WHERE licence_plate LIKE %s"
        db_cursor.execute(query, (licence_plate_fragment,))
        return db_cursor.fetchall()

