import os
import logging
from psycopg2 import Error, connect
from psycopg2.extras import DictCursor

class UserDatabase:
    def __init__(self, db_config):
        self.db_config = db_config
        self.db_connection = self.connect_to_db()
        self.cursor = self.db_connection.cursor(cursor_factory=DictCursor)

    def connect_to_db(self):
        try:
            return connect(
                host=self.db_config['host'],
                database=self.db_config['database'],
                user=self.db_config['user'],
                password=self.db_config['password']
            )
        except Error as e:
            logging.error(f"Error connecting to database: {e}")
            return None

    def update_email(self, user_id, new_email):
        query = """
            UPDATE users
            SET email = %s
            WHERE id = %s
        """
        try:
            self.cursor.execute(query, (new_email, user_id))
            self.db_connection.commit()
            return True
        except Error as e:
            logging.error(f"Error updating user email: {e}")
            self.db_connection.rollback()
            return False

def get_user_id_from_env():
    user_id = os.environ.get('USER_ID')
    if not user_id:
        raise ValueError("USER_ID environment variable is not set")
    return int(user_id)

if __name__ == '__main__':
    db_config = {
        'host': 'localhost',
        'database': 'mydatabase',
        'user': 'myuser',
        'password': 'mypassword'
    }
    user_id = get_user_id_from_env()
    db = UserDatabase(db_config)
    if db:
        user_id = get_user_id_from_env()
        new_email = 'newemail@example.com'
        if db.update_email(user_id, new_email):
            logging.info(f"User email updated successfully")
        else:
            logging.error(f"Failed to update user email")

import logging
from datetime import datetime

def parse_date(date_str):
    try:
        return datetime.strptime(date_str, '%Y-%m-%d')
    except ValueError:
        logging.error(f"Invalid date format: {date_str}")
        return None

def short_parse_date(date_str):
    if not isinstance(date_str, str) or len(date_str) != 10:
        logging.error(f"Invalid date string: {date_str}")
        return None
    return parse_date(date_str)

def is_valid_date(date_str):
    if not isinstance(date_str, str) or len(date_str) != 10:
        return False
    try:
        datetime.strptime(date_str, '%Y-%m-%d')
        return True
    except ValueError:
        return False
